export interface Sheath { parent: 'chest' | 'pelvis'; pos: number[]; dir: number[]; normal: number[] }
export interface WeaponStances { hands: Hands; shape: WeaponShape; sheath: Sheath; idle: Stance; guard?: Stance; sheathed?: Stance }
